cAAASvrGrpConfigDeadTime = MibTableColumn((1, 3, 6, 1, 4, 1, 9, 9, 367, 1, 4, 1, 1, 6), TimeIntervalMin().subtype(subtypeSpec=ValueRangeConstraint(0, 1440)).clone(0)).setUnits('minutes').setMaxAccess("readcreate")
